INSERT OR IGNORE INTO programs (id,workspace_id,name,description,owner_user_id,status,goals_json,created_at,updated_at) VALUES ('program_institutional_empowerment_2026','ws_makeen_demo','التمكين المؤسسي وتطوير الأنظمة','تعزيز كفاءة واستدامة منظمات المجتمع المدني وتطوير قدراتها المؤسسية والإدارية والتقنية.','usr_seed_admin','active','["تعزيز قدرات منظمات المجتمع المدني","رفع الوعي بالتحول الرقمي","التمهيد لتقييم الجاهزية والخطط المستقبلية"]','2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshops (id,workspace_id,program_id,slug,title,subtitle,description,delivery_mode,timezone,start_at,end_at,capacity,registration_mode,registration_approval,status,visibility,completion_rule_json,settings_json,created_by,created_at,updated_at) VALUES ('workshop_dt_why_2026','ws_makeen_demo','program_institutional_empowerment_2026','digital-transformation-why-2026','التحول الرقمي في منظمات المجتمع المدني: لماذا؟','من قناعة القيادة إلى أثر أفضل على المستفيد النهائي','ورشة قيادية تفاعلية تعزز وعي وقناعة مديري 22 منظمة بأهمية التحول الرقمي وعلاقته بجودة رحلة المستفيد. لا تتضمن في هذه المرحلة شراء برامج أو بناء أنظمة أو تقييم جاهزية تفصيلي أو إعداد استراتيجية تحول كاملة.','in_person','Asia/Aden','2026-09-23T05:30:00.000Z','2026-09-23T09:30:00.000Z',30,'invite_only','manual','scheduled','private','{"minimumAttendancePercent":75,"requiredActivities":["activity_pre_pulse","activity_beneficiary_journey","activity_problem_impact","activity_digital_opportunity","activity_leadership_commitment","activity_post_pulse"]}','{"offlineDrafts":true,"livePollSeconds":3,"beneficiaryDataWarning":true}','usr_seed_admin','2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
