-- Workshop objectives, axes and one workshop day.
INSERT OR IGNORE INTO workshop_objectives (id,workspace_id,workshop_id,title,description,success_indicator,position,created_at,updated_at) VALUES ('obj_main','ws_makeen_demo','workshop_dt_why_2026','تعزيز قناعة القيادات بأهمية التحول الرقمي','أن يرى المدير التحول الرقمي كتحسين لطريقة تقديم القيمة للمستفيد، لا كمجرد شراء تقنية.','ارتفاع متوسط القناعة البعدية وإمكانية شرح العلاقة بين مشكلة المستفيد وفرصة التحسين الرقمي.',1,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_objectives (id,workspace_id,workshop_id,title,description,success_indicator,position,created_at,updated_at) VALUES ('obj_concepts','ws_makeen_demo','workshop_dt_why_2026','تكوين فهم مشترك للمفهوم','التمييز بين رقمنة مستند، أتمتة خطوة، والتحول الذي يعيد تصميم رحلة أو قرار.','يصنف المشارك أمثلة عملية تصنيفًا صحيحًا.',2,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_objectives (id,workspace_id,workshop_id,title,description,success_indicator,position,created_at,updated_at) VALUES ('obj_beneficiary','ws_makeen_demo','workshop_dt_why_2026','ربط التحول الرقمي بتجربة المستفيد','اكتشاف أين يحدث التأخير أو الغموض أو الانقطاع في رحلة خدمة واحدة.','كل مجموعة تنتج رحلة ومشكلة واحدة وآثارًا واضحة.',3,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_objectives (id,workspace_id,workshop_id,title,description,success_indicator,position,created_at,updated_at) VALUES ('obj_action','ws_makeen_demo','workshop_dt_why_2026','تحويل الوعي إلى خطوة قابلة للتنفيذ','صياغة فرصة رقمية أولية وخطوة قيادة خلال 30 يومًا دون القفز إلى أداة بعينها.','كل منظمة تسلم بطاقة فرصة أولية وكل مدير يسجل التزامًا.',4,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_axes (id,workspace_id,workshop_id,title,description,position,created_at,updated_at) VALUES ('axis_why','ws_makeen_demo','workshop_dt_why_2026','لماذا التحول الرقمي؟','القيمة والكفاءة والإنصاف والوصول والتعلم المؤسسي.',1,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_axes (id,workspace_id,workshop_id,title,description,position,created_at,updated_at) VALUES ('axis_beneficiary_journey','ws_makeen_demo','workshop_dt_why_2026','رحلة المستفيد','رؤية الخدمة من منظور المستفيد لا من هيكل الأقسام.',2,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_axes (id,workspace_id,workshop_id,title,description,position,created_at,updated_at) VALUES ('axis_problem_impact','ws_makeen_demo','workshop_dt_why_2026','من المشكلة إلى الأثر','كشف علاقة المشكلة التشغيلية بتجربة المستفيد وجودة الخدمة والأثر التنموي.',3,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_axes (id,workspace_id,workshop_id,title,description,position,created_at,updated_at) VALUES ('axis_opportunity','ws_makeen_demo','workshop_dt_why_2026','الفرصة الرقمية قبل الأداة','صياغة تحسين مرغوب ومؤشر نجاح ومتطلبات أولية دون اختيار برنامج سريعًا.',4,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_axes (id,workspace_id,workshop_id,title,description,position,created_at,updated_at) VALUES ('axis_leadership','ws_makeen_demo','workshop_dt_why_2026','دور القيادة والخطوة التالية','أسئلة وقرارات يملكها المدير تمهد لتقييم الجاهزية والخطط في المرحلة القادمة.',5,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');
INSERT OR IGNORE INTO workshop_days (id,workspace_id,workshop_id,day_date,title,start_time,end_time,position,created_at,updated_at) VALUES ('day_dt_2026_09_23','ws_makeen_demo','workshop_dt_why_2026','2026-09-23','اليوم التدريبي','08:30','12:30',1,'2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');

