INSERT OR IGNORE INTO workshop_templates (id,workspace_id,name,category,description,version_no,blueprint_json,source_workshop_id,status,created_by,created_at,updated_at) VALUES ('template_dt_why_v1','ws_makeen_demo','ورشة لماذا التحول الرقمي؟','التحول الرقمي','قالب وعي قيادي لأربع ساعات يربط التحول الرقمي برحلة المستفيد.',1,'{"title":"التحول الرقمي في منظمات المجتمع المدني: لماذا؟","subtitle":"من قناعة القيادة إلى أثر أفضل على المستفيد النهائي","deliveryMode":"in_person","timezone":"Asia/Aden","objectives":[{"id":"obj_main","title":"تعزيز قناعة القيادات بأهمية التحول الرقمي","description":"أن يرى المدير التحول الرقمي كتحسين لطريقة تقديم القيمة للمستفيد، لا كمجرد شراء تقنية.","successIndicator":"ارتفاع متوسط القناعة البعدية وإمكانية شرح العلاقة بين مشكلة المستفيد وفرصة التحسين الرقمي."},{"id":"obj_concepts","title":"تكوين فهم مشترك للمفهوم","description":"التمييز بين رقمنة مستند، أتمتة خطوة، والتحول الذي يعيد تصميم رحلة أو قرار.","successIndicator":"يصنف المشارك أمثلة عملية تصنيفًا صحيحًا."},{"id":"obj_beneficiary","title":"ربط التحول الرقمي بتجربة المستفيد","description":"اكتشاف أين يحدث التأخير أو الغموض أو الانقطاع في رحلة خدمة واحدة.","successIndicator":"كل مجموعة تنتج رحلة ومشكلة واحدة وآثارًا واضحة."},{"id":"obj_action","title":"تحويل الوعي إلى خطوة قابلة للتنفيذ","description":"صياغة فرصة رقمية أولية وخطوة قيادة خلال 30 يومًا دون القفز إلى أداة بعينها.","successIndicator":"كل منظمة تسلم بطاقة فرصة أولية وكل مدير يسجل التزامًا."}],"axes":[{"id":"axis_why","title":"لماذا التحول الرقمي؟","description":"القيمة والكفاءة والإنصاف والوصول والتعلم المؤسسي."},{"id":"axis_beneficiary_journey","title":"رحلة المستفيد","description":"رؤية الخدمة من منظور المستفيد لا من هيكل الأقسام."},{"id":"axis_problem_impact","title":"من المشكلة إلى الأثر","description":"كشف علاقة المشكلة التشغيلية بتجربة المستفيد وجودة الخدمة والأثر التنموي."},{"id":"axis_opportunity","title":"الفرصة الرقمية قبل الأداة","description":"صياغة تحسين مرغوب ومؤشر نجاح ومتطلبات أولية دون اختيار برنامج سريعًا."},{"id":"axis_leadership","title":"دور القيادة والخطوة التالية","description":"أسئلة وقرارات يملكها المدير تمهد لتقييم الجاهزية والخطط في المرحلة القادمة."}],"agenda":[{"id":"agenda_01","start":"08:30","end":"08:45","type":"opening","title":"افتتاح ونبضة البداية","description":"توقعات واتفاق المشاركة وقياس قبلي سريع.","activityId":"activity_pre_pulse"},{"id":"agenda_02","start":"08:45","end":"09:15","type":"presentation","title":"التحول الرقمي: لماذا قبل ماذا؟","description":"أمثلة تقارن الرقمنة والأتمتة والتحول من زاوية قيمة المستفيد."},{"id":"agenda_03","start":"09:15","end":"09:45","type":"discussion","title":"سيناريو مستفيد: أين ضاعت القيمة؟","description":"حالة ميسرة تمنح الجميع لغة مشتركة حتى لو لم يقدم المديرون مشكلات من واقعهم."},{"id":"agenda_04","start":"09:45","end":"10:25","type":"activity","title":"نشاط جماعي: خريطة رحلة المستفيد","description":"كل مجموعة تختار خدمة واحدة وترسم مراحلها ونقطة ألم واحدة.","activityId":"activity_beneficiary_journey"},{"id":"agenda_05","start":"10:25","end":"10:35","type":"break","title":"استراحة"},{"id":"agenda_06","start":"10:35","end":"11:15","type":"activity","title":"نشاط جماعي: سلسلة المشكلة والأثر","description":"المشكلة ← تجربة المستفيد ← جودة الخدمة ← الأثر والثقة.","activityId":"activity_problem_impact"},{"id":"agenda_07","start":"11:15","end":"11:40","type":"group_presentations","title":"عرض المخرجات وعدسة الفرصة الرقمية","description":"عرض مختصر للمجموعات واستخلاص ما ينبغي تحسينه قبل الحديث عن الأدوات."},{"id":"agenda_08","start":"11:40","end":"12:10","type":"activity","title":"عمل كل منظمة: بطاقة فرصة رقمية أولية","description":"يعمل كل مدير منفردًا أو مع ممثل منظمته إن وُجد، مستفيدًا من تحليل المجموعة.","activityId":"activity_digital_opportunity"},{"id":"agenda_09","start":"12:10","end":"12:25","type":"activity","title":"التزام قيادي ونبضة بعدية","description":"خطوة خلال 30 يومًا وقياس ما تغير في القناعة والفهم.","activityId":"activity_leadership_commitment"},{"id":"agenda_10","start":"12:25","end":"12:30","type":"closing","title":"إغلاق وربط المرحلة القادمة","description":"تمهيد لتقييم الجاهزية وخطط التحول في الأنشطة المستقبلية.","activityId":"activity_post_pulse"}],"activities":[{"id":"activity_pre_pulse","title":"النبضة القبلية","type":"survey","ownershipMode":"individual"},{"id":"activity_beneficiary_journey","title":"خريطة رحلة المستفيد","type":"group_exercise","ownershipMode":"group"},{"id":"activity_problem_impact","title":"سلسلة المشكلة والأثر","type":"group_exercise","ownershipMode":"group"},{"id":"activity_digital_opportunity","title":"بطاقة فرصة رقمية أولية","type":"individual_exercise","ownershipMode":"organization"},{"id":"activity_leadership_commitment","title":"التزام قيادي لمدة 30 يومًا","type":"commitment","ownershipMode":"individual"},{"id":"activity_post_pulse","title":"النبضة البعدية وتقييم الورشة","type":"survey","ownershipMode":"individual"}]}','workshop_dt_why_2026','active','usr_seed_admin','2026-09-09T00:00:00.000Z','2026-09-09T00:00:00.000Z');

